/*! anime.js-compatible lightweight runtime for local CV Profile animations */
(function(global){
  "use strict";
  const Easings={
    linear:t=>t,
    easeOutQuad:t=>1-(1-t)*(1-t),
    easeOutCubic:t=>1-Math.pow(1-t,3),
    easeOutExpo:t=>t===1?1:1-Math.pow(2,-10*t)
  };
  const now=()=>performance.now();
  const toArray=(targets)=>{
    if(Array.isArray(targets)){
      return targets.flatMap(item=>typeof item==="string"?Array.from(document.querySelectorAll(item)):(item?[item]:[]));
    }
    return Array.from(typeof targets==="string"?document.querySelectorAll(targets):(targets?targets.length!==undefined?targets:[targets]:[]));
  };
  const parseValue=(value,from)=>{
    if(Array.isArray(value)) return {from:parseFloat(value[0]),to:parseFloat(value[1]),unit:String(value[1]).replace(/[-.\d]/g,"")||""};
    const numeric=parseFloat(value);
    return {from:from??0,to:Number.isFinite(numeric)?numeric:0,unit:String(value).replace(/[-.\d]/g,"")||""};
  };
  const apply=(el,key,val)=>{
    if(key==="opacity") el.style.opacity=val;
    else if(key==="translateY"||key==="translateX"||key==="scale"){
      const numeric=parseFloat(val);
      const tx=el.__animeTx||0,ty=el.__animeTy||0,sc=el.__animeScale||1;
      if(key==="translateX") el.__animeTx=Number.isFinite(numeric)?numeric:0;
      if(key==="translateY") el.__animeTy=Number.isFinite(numeric)?numeric:0;
      if(key==="scale") el.__animeScale=Number.isFinite(numeric)?numeric:1;
      el.style.transform=`translate3d(${el.__animeTx??tx}px,${el.__animeTy??ty}px,0) scale(${el.__animeScale??sc})`;
    } else if(key==="rotate"){
      el.style.transform=`rotate(${val}deg)`;
    }
  };
  function anime(params){
    const targets=toArray(params.targets);
    const duration=params.duration??1000;
    const delayBase=params.delay??0;
    const easing=Easings[params.easing]||Easings.easeOutQuad;
    const keys=Object.keys(params).filter(k=>!["targets","duration","delay","easing","complete"].includes(k));
    let finished=0;
    if(!targets.length){ params.complete&&params.complete(); return {finished:Promise.resolve()}; }
    const promises=targets.map((el,i)=>new Promise(resolve=>{
      const delay=typeof delayBase==="function"?delayBase(el,i,targets.length):delayBase;
      const startStyles={};
      keys.forEach(key=>{
        if(key==="opacity") startStyles[key]=parseFloat(getComputedStyle(el).opacity)||0;
        else if(key==="translateY") startStyles[key]=el.__animeTy||0;
        else if(key==="translateX") startStyles[key]=el.__animeTx||0;
        else if(key==="scale") startStyles[key]=el.__animeScale||1;
      });
      const values=keys.reduce((acc,key)=>{ acc[key]=parseValue(params[key],startStyles[key]); return acc; },{});
      const start=now()+delay;
      const tick=()=>{
        const t=Math.min(1,Math.max(0,(now()-start)/duration));
        if(t>0){
          const p=easing(t);
          keys.forEach(key=>{
            const item=values[key];
            const val=item.from+(item.to-item.from)*p;
            apply(el,key,`${val}${item.unit}`);
          });
        }
        if(t<1) requestAnimationFrame(tick);
        else { finished+=1; resolve(); if(finished===targets.length&&params.complete) params.complete(); }
      };
      requestAnimationFrame(tick);
    }));
    return {finished:Promise.all(promises)};
  }
  anime.stagger=(step,opts={})=>(el,i)=>((opts.start||0)+(i*step));
  anime.timeline=function(options={}){
    let offset=0;
    const tl={add(params,position){
      const at=typeof position==="number"?position:offset;
      const originalDelay=params.delay||0;
      const duration=params.duration??1000;
      anime({...params,delay:(el,i,total)=>at+(typeof originalDelay==="function"?originalDelay(el,i,total):originalDelay)});
      offset=Math.max(offset,at+duration);
      return tl;
    }};
    if(options.autoplay===false) tl.play=()=>tl;
    return tl;
  };
  global.anime=anime;
})(window);
